function stampSeg(a,b){
  const buf=S.buf; const flow=a.flow;
  const w = Math.min(9.5, 0.8 + Math.pow(flow,0.32)*(st==='schematic'?0.55:(0.95+P.branch*0.6)));
  buf.push(); buf.strokeCap(ROUND);
  let h,s,br;
