  else if (st==='schematic'){ h=190; s=52; br=78; }
  else if (st==='nerve'){ h=(342+b.gen*1.4)%360; s=80; br=54+Math.min(36,flow*2.5); }
  else if (st==='thermal'){ const ht=1-Math.min(1,b.gen/(S.maxGen*0.8+1)); h=(210-192*ht); s=84; br=52+ht*44; }
  else { h=(P.hue+b.gen*1.2)%360; s=40; br=62+Math.min(32,flow*2.2); }
