}

function growIter(burst){
  const nodes=S.nodes, attr=S.attr, di=S.di, dk=S.dk, seg=S.seg, cs=di;
  if (nodes.length>=S.cap) return;
  const map=new Map();
  for (let i=0;i<nodes.length;i++){ const p=nodes[i]; const k=Math.floor(p.x/cs)+','+Math.floor(p.y/cs); let b=map.get(k); if(!b){b=[];map.set(k,b);} b.push(i); }
  const pull=new Map();
  for (let ai=attr.length-1; ai>=0; ai--){ const a=attr[ai];
    let best=-1, bd=di*di; const bx=Math.floor(a.x/cs), by=Math.floor(a.y/cs);
    for (let ox=-1;ox<=1;ox++) for (let oy=-1;oy<=1;oy++){ const b=map.get((bx+ox)+','+(by+oy)); if(!b) continue;
      for (let jj=0;jj<b.length;jj++){ const j=b[jj], p=nodes[j], d2=(p.x-a.x)*(p.x-a.x)+(p.y-a.y)*(p.y-a.y); if(d2<bd){bd=d2;best=j;} } }
    if (best<0) continue;
    if (bd < dk*dk){ attr.splice(ai,1); continue; }
    const p=nodes[best], d=Math.sqrt(bd)||1; let e=pull.get(best)||{dx:0,dy:0};
    e.dx+=(a.x-p.x)/d; e.dy+=(a.y-p.y)/d; pull.set(best,e);
  }
  if (pull.size===0) return;
  pull.forEach((e,idx)=>{ if (nodes.length>=S.cap) return;
    const p=nodes[idx];
    let dx=e.dx, dy=e.dy; const om=Math.hypot(p.x-ax,p.y-ay)||1;
    dx += (p.x-ax)/om*0.5; dy += (p.y-ay)/om*0.5;
    const wob=(S.rnd()-0.5)*0.6, cw=Math.cos(wob), sw=Math.sin(wob);
    const rx=dx*cw-dy*sw, ry=dx*sw+dy*cw, m=Math.hypot(rx,ry)||1;
    const nx=p.x+rx/m*seg, ny=p.y+ry/m*seg;
    const gen=p.gen+1; if(gen>S.maxGen)S.maxGen=gen;
    const ni=nodes.length; nodes.push({x:nx,y:ny,par:idx,gen:gen,flow:1});
    let k=idx,guard=0; while(k>=0 && guard++<2000){ nodes[k].flow++; k=nodes[k].par; }
    stampSeg(p, nodes[ni]);
    if(!burst) S.fresh.push(ni);
    S.leaf=ni;
  });
}

const epoch = Math.floor((K.section||0)/2);
const key = width+'x'+height+'|'+P.seed+'|'+epoch+'|'+st+'|'+P.branch.toFixed(2)+'|'+P.scale.toFixed(2);
if (S.key !== key){
  S.key = key;
  let z = ((P.seed*2654435761) ^ (epoch*40503) ^ 0x1F) >>> 0;
  S.rnd = ()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  if (!S.buf || S.bufKey!==width+'x'+height){ if (S.buf) S.buf.remove(); S.buf=createGraphics(width,height); S.buf.colorMode(HSB,360,100,100,100); S.bufKey=width+'x'+height; }
  S.maxGen=1;
  grd(S.buf);
  S.di = u*(0.16 - P.branch*0.09);
  S.seg = u*(0.012 + P.scale*0.006);
  S.dk = S.seg*1.7;
  S.cap = Math.floor(500 + P.density*1100);
  const NA = Math.floor(120 + P.density*520);
  S.attr = [];
