    if (S.rnd()<0.5){ S.attr.push({x:S.rnd()*width, y:S.rnd()*height}); }
    else { const a=S.rnd()*6.2832, rr=u*0.52*Math.sqrt(S.rnd()); S.attr.push({x:clp(ax+Math.cos(a)*rr,2,width-2), y:clp(ay+Math.sin(a)*rr,2,height-2)}); }
  }
  const spokes = 3 + Math.floor(P.density*7);
  S.nodes = [{x:ax,y:ay,par:-1,gen:0,flow:1}];
  for (let s=0;s<spokes;s++){ const a=(s/spokes)*6.2832 + S.rnd()*0.8, r=S.seg*1.5; S.nodes.push({x:ax+Math.cos(a)*r, y:ay+Math.sin(a)*r, par:0, gen:1, flow:1}); }
  S.fresh=[]; S.flash=0; S.bolt=null; S.leaf=1; S.lastSec=K.section||0;
  const target = Math.min(S.cap, Math.floor(240 + P.density*280));
  let guard=0;
  while (S.nodes.length < target && guard++ < 700){ const before=S.nodes.length; growIter(true); if(S.nodes.length===before){ for(let q=0;q<10;q++){ const pp=S.nodes[(S.rnd()*S.nodes.length)|0], a2=S.rnd()*6.2832, rr=S.di*(0.5+S.rnd()*0.45); S.attr.push({x:clp(pp.x+Math.cos(a2)*rr,2,width-2), y:clp(pp.y+Math.sin(a2)*rr,2,height-2)}); } } }
  const f0=Math.max(1,S.nodes.length-150); for(let i=f0;i<S.nodes.length;i++) S.fresh.push(i);
}

if (S.nodes.length < S.cap && S.attr.length < 30){
  for (let i=0;i<12;i++){ const pp=S.nodes[(S.rnd()*S.nodes.length)|0], a=S.rnd()*6.2832, rr=S.di*(0.5+S.rnd()*0.5); S.attr.push({x:clp(pp.x+Math.cos(a)*rr,2,width-2), y:clp(pp.y+Math.sin(a)*rr,2,height-2)}); }
}
const growN = (S.nodes.length>=S.cap) ? 0 : Math.max(1, Math.round((1+P.speed*2.2)*(0.6+intn) + A.bass*4));
for (let i=0;i<growN;i++){ if(S.nodes.length>=S.cap) break; growIter(false); }

const drx=Math.sin(K.t*0.11)*u*0.012, dry=Math.cos(K.t*0.09)*u*0.010;
push();
