if (st!=='schematic') blendMode(ADD);
noStroke();
const eg = 0.5 + P.energy*0.9;
for (let i=0;i<fr.length;i++){ const idx=fr[i]; const p=S.nodes[idx]; if(!p) continue;
  const age=(fr.length-1-i)/Math.max(1,fr.length), flare=1-age;
  const sh=0.4+0.6*Math.sin(K.t*3.2 - i*0.2), bri=flare*(0.55+0.45*sh);
