  else if (st==='nerve'){h=(320+(i%2)*42)%360;s=72;}
  else if (st==='thermal'){h=(28+flare*14);s=82;}
  else if (st==='schematic'){h=190;s=22;}
  else {h=(P.hue-18+p.gen*0.8+360)%360;s=clp(30-flare*22,0,100);}
  const a2 = (10+bri*40)*eg*(st==='schematic'?0.45:1) + A.treble*30*flare;
  if (i>=fr.length-12 && st!=='schematic'){ drawingContext.shadowBlur=10*eg; drawingContext.shadowColor='hsla('+((h)|0)+',90%,72%,0.9)'; }
